    indexOf(value, byteOffset = 0) {
        const needle = typeof value === 'string' ? encodedBytes(value) : MochiBuffer.from(value);
        if (!needle.length) return 0;
        for (let i = Math.max(0, byteOffset); i + needle.length <= this.length; i++) {
            let ok = true;
            for (let j = 0; j < needle.length; j++) if (this[i + j] !== needle[j]) { ok = false; break; }
            if (ok) return i;
        }
        return -1;
    }

