const INTEGER_METHODS = [
    ['UInt8', 1, false, 'Uint8'], ['Int8', 1, true, 'Int8'],
    ['UInt16LE', 2, false, 'Uint16', true], ['UInt16BE', 2, false, 'Uint16', false],
    ['Int16LE', 2, true, 'Int16', true], ['Int16BE', 2, true, 'Int16', false],
    ['UInt32LE', 4, false, 'Uint32', true], ['UInt32BE', 4, false, 'Uint32', false],
    ['Int32LE', 4, true, 'Int32', true], ['Int32BE', 4, true, 'Int32', false],
];

for (const [name, size, signed, view, little] of INTEGER_METHODS) {
    const reader = 'read' + name;
    const writer = 'write' + name;
    const littleEndian = little === true;
    MochiBuffer.prototype[reader] = function (offset = 0) {
        const v = new DataView(this.buffer, this.byteOffset, this.byteLength);
        const raw = little === undefined ? v['get' + view](offset) : v['get' + view](offset, littleEndian);
        return signed && size === 1 ? (raw << 24) >> 24 : raw;
    };
    MochiBuffer.prototype[writer] = function (value, offset = 0) {
        const v = new DataView(this.buffer, this.byteOffset, this.byteLength);
        if (little === undefined) v['set' + view](offset, value);
        else v['set' + view](offset, value, littleEndian);
        return offset + size;
    };
}

for (const [name, little] of [['FloatLE', true], ['FloatBE', false], ['DoubleLE', true], ['DoubleBE', false]]) {
    const type = name.startsWith('Float') ? 'Float32' : 'Float64';
    const size = type === 'Float32' ? 4 : 8;
    MochiBuffer.prototype['read' + name] = function (offset = 0) {
        return new DataView(this.buffer, this.byteOffset, this.byteLength)['get' + type](offset, little);
    };
    MochiBuffer.prototype['write' + name] = function (value, offset = 0) {
        new DataView(this.buffer, this.byteOffset, this.byteLength)['set' + type](offset, value, little);
        return offset + size;
    };
}

for (const [name, little] of [['BigUInt64BE', false], ['BigUInt64LE', true], ['BigInt64BE', false], ['BigInt64LE', true]]) {
    const type = name.startsWith('BigUInt') ? 'BigUint64' : 'BigInt64';
    MochiBuffer.prototype['read' + name] = function (offset = 0) {
        return new DataView(this.buffer, this.byteOffset, this.byteLength)['get' + type](offset, little);
    };
    MochiBuffer.prototype['write' + name] = function (value, offset = 0) {
        new DataView(this.buffer, this.byteOffset, this.byteLength)['set' + type](offset, BigInt(value), little);
        return offset + 8;
    };
}

MochiBuffer.prototype.__mochiBuffer = true;

export const Buffer = MochiBuffer;
export default MochiBuffer;

if (!globalThis.Buffer) { try { globalThis.Buffer = MochiBuffer; } catch {} }
